  1	#!/bin/sh
  2	set -eu
  3	
  4	terraform_bin="${TERRAFORM_BIN:-terraform}"
  5	environment_dir="infra/environments/prod"
  6	bucket="$($terraform_bin -chdir="$environment_dir" output -raw dashboard_bucket_name)"
  7	distribution_id="$($terraform_bin -chdir="$environment_dir" output -raw cloudfront_distribution_id)"
  8	
  9	aws s3 sync dashboard/out/ "s3://$bucket/" --delete --only-show-errors
 10	invalidation_id="$(aws cloudfront create-invalidation \
 11	  --distribution-id "$distribution_id" \
 12	  --paths '/*' \
 13	  --query 'Invalidation.Id' \
 14	  --output text)"
 15	aws cloudfront wait invalidation-completed \
 16	  --distribution-id "$distribution_id" \
 17	  --id "$invalidation_id"
